  function bulkPhoto(assign){
    const photos=S.data.photos.filter(p=>selectedPhotos.has(p.id)&&(galleryView==='all'||(galleryView==='inbox'?!p.project_id:p.project_id===galleryView)));
    if(!photos.length)throw new Error('Select photos first.');
    if(assign&&photos.some(p=>p.project_id))throw new Error('Only inbox photos can be assigned.');
    dialog(`${assign?'Assign':'Edit'} ${photos.length} photos`,assign?`<p>Selected originals will become accessible to this project’s team. Website approval stays unchanged.</p><label>Destination project<select name="project" required><option value="">Choose project</option>${options(S.data.projects.map(p=>[p.id,p.name]))}</select></label>`:`<label>Stage<select name="stage">${options([['','Keep current stage'],...['unsorted','before','during','after'].map(s=>[s,s])])}</select></label><label class="ops-check"><input type="checkbox" name="set_room"> Replace room / work area</label>${input('room','New room / work area')}<label class="ops-check"><input type="checkbox" name="set_caption"> Replace caption</label>${input('caption','New caption')}<p>Only the fields you choose are changed. A checked blank field clears its existing value.</p>`,async f=>{
      if(!assign&&!f.stage&&!f.set_room&&!f.set_caption)throw new Error('Choose at least one field to change.');
      let done=0;const failed=[];
      for(const p of photos.filter(p=>selectedPhotos.has(p.id))){try{if(assign)await S.assignPhoto(p.id,f.project);else{const latest=S.data.photos.find(x=>x.id===p.id);if(!latest)throw new Error('Photo no longer available');await S.save('photos',{...latest,...(f.stage?{stage:f.stage}:{}),...(f.set_room?{room:f.room}:{}),...(f.set_caption?{caption:f.caption}:{})});}selectedPhotos.delete(p.id);done++;}catch(e){failed.push(`${p.name||'Photo'}: ${e.message}`);}}
      refresh();if(failed.length)throw new Error(`${done} saved; ${failed.length} failed. Successful photos are deselected. Close this dialog and retry the remaining selection. ${failed.join('; ')}`);
    },'Apply to selected');
  }
