    scope:()=>{const e=estimate();dialog('Scope and assumptions',area('notes','Shared scope, exclusions, and qualifications',e.notes)+`<label class="ops-check"><input name="confirmed" type="checkbox" ${e.scope_confirmed?'checked':''}> Alex has confirmed the proposed scope and material assumptions.</label>`,f=>S.save('estimates',{...e,notes:f.notes,scope_confirmed:f.confirmed==='on'}));},
    contact:()=>{const p=project(),c=S.data.clients.find(x=>x.id===p.client_id);if(!c)throw new Error('Only the project owner can edit client records.');dialog('Project and client details',input('name','Project name',p.name,'text',true)+input('address','Property address',p.address)+input('client_name','Client name',c.name,'text',true)+input('phone','Phone',c.phone,'tel')+input('email','Email',c.email,'email')+`<label>Stage<select name="status">${options(['lead','walkthrough','estimating','review','active','complete','archived'].map(x=>[x,x]),p.status)}</select></label>`+input('next_action','Next action',p.next_action||'Schedule walkthrough','text',true)+input('next_action_due','Next action due',p.next_action_due,'date'),async f=>{await S.save('clients',{...c,name:f.client_name,phone:f.phone,email:f.email});await S.save('projects',{...p,name:f.name,address:f.address,status:f.status,next_action:f.next_action,next_action_due:f.next_action_due||null});});},
