  document.addEventListener('change',ev=>{if(ev.target.matches('[data-thumbnail-size]')){try{localStorage.setItem('tagims-ops-thumbnail-size',String(thumbnailSize));}catch{}}});
  document.addEventListener('click',ev=>{document.querySelectorAll('.ops-photo-settings[open]').forEach(menu=>{if(!menu.contains(ev.target)||ev.target.closest('[data-action]'))menu.open=false;});});
  document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){document.querySelectorAll('.ops-photo-settings[open]').forEach(menu=>{menu.open=false;menu.querySelector('summary').focus();});}});
  document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-action]');if(!b||!b.closest('.ops-root,.ops-dialog'))return;try{const context=b.closest('[data-project-context-id]');if(context){selected=context.dataset.projectContextId;localStorage.setItem('tagims-ops-project',selected);}await actions[b.dataset.action]?.(b.dataset.id,b);}catch(e){status(e.message,true);}});
  document.addEventListener('click',ev=>{const b=ev.target.closest('[data-step],[data-popout]');if(!b||!b.closest('.ops-root'))return;const root=b.closest('.ops-root');if(b.dataset.popout){remember(root);const widget=window.OpsPopOut?.(b.dataset.popout),target=widget?.querySelector('.ops-root');if(target&&root._child){target._step=root._child._step;target._memory=structuredClone(root._child._memory||{});render(target);}return;}root._step=Number(b.dataset.step);render(root);});
  document.addEventListener('change',ev=>{const t=ev.target;if(t.matches('[data-photo-select]')){t.checked?selectedPhotos.add(t.dataset.photoSelect):selectedPhotos.delete(t.dataset.photoSelect);refresh();}if(t.matches('[data-photo-all]')){t.closest('.ops-root').querySelectorAll('[data-photo-select]').forEach(c=>t.checked?selectedPhotos.add(c.dataset.photoSelect):selectedPhotos.delete(c.dataset.photoSelect));refresh();}if(t.matches('[data-upload-destination]'))uploadDestination=t.value;if(t.matches('[data-gallery-view]')){selectedPhotos.clear();galleryView=t.value;refresh();}});
  document.addEventListener('change',async ev=>{const t=ev.target;try{if(t.matches('[data-project]'))choose(t.value);if(t.matches('[data-complete]')){const x=S.data.field_items.find(x=>x.id===t.dataset.complete);await S.save('field_items',{...x,status:t.checked?'done':'open'});}if(t.matches('[data-upload]')){if(busy)throw new Error('Wait for the current upload to finish.');busy=true;const id=uploadDestination||null,files=Array.from(t.files);let saved=0;const failures=[];for(const file of files){status(`Saving ${file.name}…`);try{await S.upload(id,file);saved++;}catch(e){failures.push(file.name+': '+e.message);}}status(`${saved} photo(s) saved ${S.mode==='cloud'?'to shared storage':'on this browser'}.${failures.length?' Failed: '+failures.join('; '):''}`,failures.length>0);if(!failures.length)t.value='';busy=false;}}catch(e){busy=false;status(e.message,true);refresh();}});
  const renderers=Object.fromEntries(Object.keys(labels).map(type=>[type,()=>{const el=document.createElement('div');el.className='ops-root hub-data-widget';el.dataset.opsType=type;roots.add(el);render(el);return el;}]));
