    document.addEventListener('pointerup',e=>{if(!drag||drag.pointer!==e.pointerId)return;const d=drag;clear();if(d.moved){suppressClick=true;setTimeout(()=>suppressClick=false,0);e.preventDefault();e.stopPropagation();if(d.target)Promise.resolve().then(()=>commit(d.id,d.target)).catch(err=>status(err.message,true));}},true);
    document.addEventListener('click',e=>{if(suppressClick){suppressClick=false;e.preventDefault();e.stopImmediatePropagation();}},true);
