        originals.forEach((original,i)=>{const copy=copies[i],style=getComputedStyle(original);for(const name of style)copy.style.setProperty(name,style.getPropertyValue(name));for(const attribute of [...copy.attributes])if(attribute.name!=='style'&&attribute.name!=='class')copy.removeAttribute(attribute.name);copy.style.pointerEvents='none';copy.style.animation='none';copy.style.transition='none';});
        clone.style.margin='0';clone.style.width=d.box.width+'px';clone.style.height=d.box.height+'px';clone.style.transform='none';
